import{_ as a,o as e,c as l,ag as s}from"./chunks/framework.CGaGjEnN.js";const u=JSON.parse('{"title":"关于 unified-music-api","description":"","frontmatter":{},"headers":[],"relativePath":"intro/about.md","filePath":"intro/about.md","lastUpdated":1790599334000}'),t={name:"intro/about.md"};function n(o,i,p,r,c,h){return e(),l("div",null,[...i[0]||(i[0]=[s(`<h1 id="关于-unified-music-api" tabindex="-1">关于 unified-music-api <a class="header-anchor" href="#关于-unified-music-api" aria-label="Permalink to &quot;关于 unified-music-api&quot;">​</a></h1><blockquote><p>更新时间：2026-09-28</p></blockquote><h2 id="_1-项目定位" tabindex="-1">1. 项目定位 <a class="header-anchor" href="#_1-项目定位" aria-label="Permalink to &quot;1. 项目定位&quot;">​</a></h2><p>unified-music-api 是一套面向「音乐数据聚合与分发」场景的开源 API 系统，将 9 个分散的音乐 API 仓库整合为单一 TypeScript monorepo，适用于：</p><ul><li>需要网易云音乐全接口能力的应用</li><li>需要酷狗音乐数据接入的场景</li><li>灰色歌曲解锁（UNM）与多源匹配</li><li>TTML 逐字歌词获取</li><li>需要统一网关做鉴权、限流、反代的独立站业务</li></ul><h2 id="_2-核心能力" tabindex="-1">2. 核心能力 <a class="header-anchor" href="#_2-核心能力" aria-label="Permalink to &quot;2. 核心能力&quot;">​</a></h2><h3 id="_2-1-微服务架构" tabindex="-1">2.1 微服务架构 <a class="header-anchor" href="#_2-1-微服务架构" aria-label="Permalink to &quot;2.1 微服务架构&quot;">​</a></h3><ul><li><code>apps/gateway</code>：统一网关（Hono + TypeScript），鉴权、限流、平台反代</li><li><code>apps/netease</code>：网易云音乐 440 个接口</li><li><code>apps/kugou</code>：酷狗音乐 226 个接口</li><li><code>apps/unm</code>：解灰 / 多源匹配（GD Studio、QQ、酷狗、咪咕、JOOX）</li><li><code>apps/lyric</code>：TTML 逐字歌词服务</li><li><code>apps/meting</code>：Meting 聚合解析（spotify / ytmusic）</li><li><code>packages/</code>：六个共享包（ncm-crypto、http-kit 等）</li></ul><h3 id="_2-2-网关能力" tabindex="-1">2.2 网关能力 <a class="header-anchor" href="#_2-2-网关能力" aria-label="Permalink to &quot;2.2 网关能力&quot;">​</a></h3><ul><li>统一路由 <code>GET/POST /api/v1/platform/{name}/{path}</code> 反代五个平台</li><li>API Key 鉴权、IP 限流、上游地址环境变量可覆盖</li><li>原生聚合接口：<code>/api/v1/search</code>、<code>/api/v1/lyric</code>、<code>/api/v1/match</code></li></ul><h3 id="_2-3-数据能力" tabindex="-1">2.3 数据能力 <a class="header-anchor" href="#_2-3-数据能力" aria-label="Permalink to &quot;2.3 数据能力&quot;">​</a></h3><ul><li>网易云 440 接口：与上游 <code>api-enhanced</code> 全量静态比对，零缺失</li><li>酷狗 226 接口：完整承接原模块</li><li>NCM 加密（WEAPI/EAPI）经 golden 测试验证，与原版行为一致</li></ul><h3 id="_2-4-工程化" tabindex="-1">2.4 工程化 <a class="header-anchor" href="#_2-4-工程化" aria-label="Permalink to &quot;2.4 工程化&quot;">​</a></h3><ul><li>pnpm + Turborepo monorepo，Biome 格式化/ lint</li><li>每服务独立 OpenAPI 3.1 spec，Scalar 实时文档</li><li>CI 四门禁：构建/测试、覆盖率、契约（路由数）、gitleaks</li><li>Docker Compose 一键部署</li></ul><h2 id="_3-为什么选择-unified-music-api" tabindex="-1">3. 为什么选择 unified-music-api <a class="header-anchor" href="#_3-为什么选择-unified-music-api" aria-label="Permalink to &quot;3. 为什么选择 unified-music-api&quot;">​</a></h2><ul><li><strong>接口最全</strong>：网易云 440 + 酷狗 226，逐模块比对无缺失。</li><li><strong>技术栈现代</strong>：TypeScript + Hono，全类型安全，无冗余无冲突。</li><li><strong>网关统一</strong>：一个入口聚合五个平台，鉴权限流开箱即用。</li><li><strong>文档完整</strong>：本手册 + 各服务 Scalar 实时文档 + OpenAPI spec。</li><li><strong>可持续演进</strong>：monorepo 结构，加新平台只需新增 app。</li></ul><h2 id="_4-适用场景" tabindex="-1">4. 适用场景 <a class="header-anchor" href="#_4-适用场景" aria-label="Permalink to &quot;4. 适用场景&quot;">​</a></h2><ul><li>想快速接入网易云/酷狗音乐数据的个人/小团队</li><li>需要自建音乐 API 网关、保留自主可控能力的企业团队</li><li>需要在现有系统上做音乐能力定制开发的技术团队</li></ul><h2 id="_5-快速开始" tabindex="-1">5. 快速开始 <a class="header-anchor" href="#_5-快速开始" aria-label="Permalink to &quot;5. 快速开始&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/IIXINGCHEN/unified-music-api</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unified-music-api</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动全部服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>启动后访问：</p><ul><li>网关：<code>http://localhost:8080</code></li><li>网易云：<code>http://localhost:3001/docs</code></li><li>API 文档：<code>/api/</code>（本手册）</li></ul><p>详见<a href="/unified-music-api/guide/quickstart.html">快速开始</a>。</p><h2 id="_6-开源仓库与贡献" tabindex="-1">6. 开源仓库与贡献 <a class="header-anchor" href="#_6-开源仓库与贡献" aria-label="Permalink to &quot;6. 开源仓库与贡献&quot;">​</a></h2><ul><li>主仓库：<a href="https://github.com/IIXINGCHEN/unified-music-api" target="_blank" rel="noreferrer">IIXINGCHEN/unified-music-api</a></li><li>在线文档：<a href="https://iixingchen.github.io/unified-music-api/" target="_blank" rel="noreferrer">https://iixingchen.github.io/unified-music-api/</a></li></ul><p>如果你希望补充接口、修复问题或改进文档，欢迎直接提交 PR。</p>`,26)])])}const k=a(t,[["render",n]]);export{u as __pageData,k as default};
